import jsPDF from 'jspdf';
import JSZip from 'jszip';
import type { EvidenceItem, Submission, AuditEvent } from '../types';

/**
 * AICTE VerifyAI — PDF Document Download Generator
 *
 * Produces valid, readable PDF files from synthetic demo compliance data.
 * Every document carries a prominent "SAMPLE / DEMO — NOT AN OFFICIAL DOCUMENT"
 * watermark so that no generated file can be confused with an official record.
 */

export interface DownloadResult {
  success: boolean;
  filename: string;
  message: string;
  fileSizeBytes: number;
}

// ─── Colour / style constants ────────────────────────────────────────────────

const NAVY = [15, 28, 63] as const;       // Deep navy — header background
const COBALT = [37, 99, 235] as const;    // Cobalt blue — section rules
const AMBER = [180, 95, 6] as const;      // Amber — watermark text
const SLATE = [71, 85, 105] as const;     // Slate — body text
const LIGHT_BG = [245, 247, 250] as const; // Very light blue-grey — alternating rows

// ─── Helpers ─────────────────────────────────────────────────────────────────

function triggerBrowserDownload(filename: string, blob: Blob) {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.style.display = 'none';
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  setTimeout(() => URL.revokeObjectURL(url), 3000);
}

/** Convert an institution name into a safe filename stem (max 40 chars). */
function safeStem(name: string, maxLen = 40): string {
  return name
    .replace(/[^a-zA-Z0-9\s]/g, '')
    .trim()
    .replace(/\s+/g, '_')
    .slice(0, maxLen);
}

/** Draw the diagonal "SAMPLE / DEMO" watermark across the page. */
function drawWatermark(doc: jsPDF) {
  const pw = doc.internal.pageSize.getWidth();
  const ph = doc.internal.pageSize.getHeight();
  doc.saveGraphicsState();
  doc.setGState(new (doc as any).GState({ opacity: 0.07 }));
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(46);
  doc.setTextColor(AMBER[0], AMBER[1], AMBER[2]);
  doc.text('SAMPLE / DEMO', pw / 2, ph / 2, {
    align: 'center',
    angle: 45,
    baseline: 'middle',
  });
  doc.restoreGraphicsState();
}

/** Draw the top-of-page header band. Returns y after the header. */
function drawPageHeader(
  doc: jsPDF,
  institutionName: string,
  applicationId: string,
  docTitle: string,
): number {
  const pw = doc.internal.pageSize.getWidth();

  // Navy header band
  doc.setFillColor(NAVY[0], NAVY[1], NAVY[2]);
  doc.rect(0, 0, pw, 36, 'F');

  // Left: VerifyAI branding
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(14);
  doc.setTextColor(255, 255, 255);
  doc.text('AICTE VerifyAI', 12, 14);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(160, 180, 220);
  doc.text('Compliance Review Platform  ·  Smart India Hackathon Demo', 12, 21.5);

  // Right: metadata block
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7);
  doc.setTextColor(160, 180, 220);
  doc.text(`Institution: ${institutionName}`, pw - 12, 10, { align: 'right' });
  doc.text(`App ID: ${applicationId}`, pw - 12, 16, { align: 'right' });
  doc.text(`Generated: ${new Date().toISOString().slice(0, 10)}`, pw - 12, 22, { align: 'right' });

  // Cobalt accent rule
  doc.setFillColor(COBALT[0], COBALT[1], COBALT[2]);
  doc.rect(0, 36, pw, 2, 'F');

  // Document title below header
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(NAVY[0], NAVY[1], NAVY[2]);
  doc.text(docTitle, 12, 48);

  // Amber "SAMPLE / DEMO" notice bar
  doc.setFillColor(254, 243, 199);
  doc.roundedRect(12, 53, pw - 24, 10, 2, 2, 'F');
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7);
  doc.setTextColor(AMBER[0], AMBER[1], AMBER[2]);
  doc.text(
    'SAMPLE / DEMO — NOT AN OFFICIAL DOCUMENT  ·  Generated by AICTE VerifyAI for SIH evaluation only',
    pw / 2,
    59.5,
    { align: 'center' },
  );

  return 68; // return cursor Y below header
}

/** Draw a section heading and return new Y. */
function drawSection(doc: jsPDF, title: string, y: number): number {
  const pw = doc.internal.pageSize.getWidth();
  doc.setFillColor(COBALT[0], COBALT[1], COBALT[2]);
  doc.rect(12, y, 3, 7, 'F');
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8.5);
  doc.setTextColor(NAVY[0], NAVY[1], NAVY[2]);
  doc.text(title.toUpperCase(), 18, y + 5.5);
  // Light rule
  doc.setDrawColor(COBALT[0], COBALT[1], COBALT[2]);
  doc.setLineWidth(0.3);
  doc.line(18, y + 7, pw - 12, y + 7);
  return y + 12;
}

/** Render a two-column key/value table row. Returns new Y. */
function drawKVRow(
  doc: jsPDF,
  key: string,
  value: string,
  y: number,
  evenRow: boolean,
): number {
  const pw = doc.internal.pageSize.getWidth();
  const rowH = 7.5;
  if (evenRow) {
    doc.setFillColor(LIGHT_BG[0], LIGHT_BG[1], LIGHT_BG[2]);
    doc.rect(12, y, pw - 24, rowH, 'F');
  }
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.5);
  doc.setTextColor(SLATE[0], SLATE[1], SLATE[2]);
  doc.text(key, 15, y + 5.5);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(30, 30, 30);
  // Wrap long values
  const maxW = pw - 24 - 70;
  const lines = doc.splitTextToSize(value, maxW);
  doc.text(lines, 85, y + 5.5);
  const extraH = Math.max(0, (lines.length - 1) * 4.5);
  return y + rowH + extraH;
}

/** Check if we need a new page and add one if so. */
function checkPageBreak(doc: jsPDF, y: number, needed = 18): number {
  const ph = doc.internal.pageSize.getHeight();
  if (y + needed > ph - 20) {
    doc.addPage();
    drawWatermark(doc);
    drawFooter(doc);
    return 18;
  }
  return y;
}

/** Draw page footer. */
function drawFooter(doc: jsPDF) {
  const pw = doc.internal.pageSize.getWidth();
  const ph = doc.internal.pageSize.getHeight();
  doc.setFillColor(NAVY[0], NAVY[1], NAVY[2]);
  doc.rect(0, ph - 12, pw, 12, 'F');
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.5);
  doc.setTextColor(130, 150, 190);
  doc.text(
    'SAMPLE / DEMO — NOT AN OFFICIAL DOCUMENT  ·  AICTE VerifyAI Prototype  ·  Smart India Hackathon',
    pw / 2,
    ph - 4.5,
    { align: 'center' },
  );
}

// ─── PDF generators ───────────────────────────────────────────────────────────

/** Build a single-document PDF for one EvidenceItem. Returns the jsPDF instance. */
export function buildDocumentPdf(doc: EvidenceItem, submission: Submission): jsPDF {
  const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const pw = pdf.internal.pageSize.getWidth();

  drawWatermark(pdf);
  drawFooter(pdf);

  const title = doc.name;
  let y = drawPageHeader(pdf, submission.institution.name, submission.applicationId, title);

  // ── Document Metadata ──────────────────────────────────────────────────────
  y = drawSection(pdf, 'Document Metadata', y);
  const metaRows: [string, string][] = [
    ['Document Title', doc.name],
    ['Document Type', doc.type.toUpperCase().replace(/_/g, ' ')],
    ['Filename', doc.filename ?? `${safeStem(doc.name)}.pdf`],
    ['Uploaded', doc.uploadedAt],
    ['Verification Status', doc.verificationStatus.toUpperCase()],
    ['Issuing Authority', doc.issuer ?? 'Simulated Authority Desk'],
    ['SHA-256 Checksum', doc.checksumSha256 ?? 'd7a8fbb307d7809469ca9abcb0082e4f8d5651e46d3cdb762d02d0bf37c9e592'],
    ['Page Count', `${doc.pageCount ?? 1} page(s)`],
  ];
  metaRows.forEach(([k, v], i) => {
    y = checkPageBreak(pdf, y);
    y = drawKVRow(pdf, k, v, y, i % 2 === 0);
  });
  y += 4;

  // ── Institution Context ────────────────────────────────────────────────────
  y = checkPageBreak(pdf, y, 50);
  y = drawSection(pdf, 'Institution & Application Context', y);
  const instRows: [string, string][] = [
    ['Institution Legal Name', `${submission.institution.name}  (SAMPLE / FICTIONAL ENTITY)`],
    ['AICTE Institute ID', submission.institution.aicteId],
    ['Application ID', submission.applicationId],
    ['Campus Location', `${submission.institution.city}, ${submission.institution.state}`],
    ['Application Category', submission.category],
    ['Submission Status', submission.status.toUpperCase().replace(/_/g, ' ')],
    ['Priority Score', `${submission.priorityScore} / 100`],
    ['Due Date', submission.dueDate],
  ];
  instRows.forEach(([k, v], i) => {
    y = checkPageBreak(pdf, y);
    y = drawKVRow(pdf, k, v, y, i % 2 === 0);
  });
  y += 4;

  // ── Review Purpose ─────────────────────────────────────────────────────────
  if (doc.description) {
    y = checkPageBreak(pdf, y, 30);
    y = drawSection(pdf, 'Review Purpose', y);
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(8);
    pdf.setTextColor(SLATE[0], SLATE[1], SLATE[2]);
    const descLines = pdf.splitTextToSize(doc.description, pw - 27);
    pdf.text(descLines, 15, y);
    y += descLines.length * 4.5 + 4;
  }

  // ── Advisory Note ──────────────────────────────────────────────────────────
  if (doc.notes) {
    y = checkPageBreak(pdf, y, 30);
    pdf.setFillColor(254, 252, 232);
    pdf.roundedRect(12, y, pw - 24, 14, 2, 2, 'F');
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(7.5);
    pdf.setTextColor(AMBER[0], AMBER[1], AMBER[2]);
    pdf.text('⚠  Advisory Note', 16, y + 5.5);
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(7.5);
    pdf.setTextColor(30, 30, 30);
    const noteLines = pdf.splitTextToSize(doc.notes, pw - 32);
    pdf.text(noteLines, 16, y + 11);
    y += 16 + (noteLines.length - 1) * 4 + 4;
  }

  // ── Document Body / Extracted Content ─────────────────────────────────────
  y = checkPageBreak(pdf, y, 30);
  y = drawSection(pdf, 'Extracted Document Content', y);

  if (doc.content?.pages && doc.content.pages.length > 0) {
    doc.content.pages.forEach((page) => {
      y = checkPageBreak(pdf, y, 20);
      // Page label
      pdf.setFillColor(NAVY[0], NAVY[1], NAVY[2]);
      pdf.roundedRect(12, y, pw - 24, 7, 1.5, 1.5, 'F');
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(7);
      pdf.setTextColor(255, 255, 255);
      pdf.text(
        `PAGE ${page.pageNumber} OF ${doc.content!.pages.length}  ·  ${doc.content!.headerTitle ?? doc.name}`,
        pw / 2,
        y + 4.5,
        { align: 'center' },
      );
      y += 10;

      page.paragraphs.forEach((para) => {
        y = checkPageBreak(pdf, y, 18);
        if (para.isDiscrepancy) {
          // Highlighted finding paragraph
          pdf.setFillColor(254, 226, 226);
          pdf.roundedRect(12, y, pw - 24, 4, 1, 1, 'F');
          pdf.setFont('helvetica', 'bold');
          pdf.setFontSize(6.5);
          pdf.setTextColor(185, 28, 28);
          pdf.text(
            `⚑  ADVISORY FLAG: ${para.annotationTitle ?? 'Automated Discrepancy'}`,
            15,
            y + 3,
          );
          y += 5.5;
        }
        pdf.setFont('helvetica', 'normal');
        pdf.setFontSize(8);
        pdf.setTextColor(30, 30, 30);
        const paraLines = pdf.splitTextToSize(para.text, pw - 27);
        pdf.text(paraLines, 15, y);
        y += paraLines.length * 4.5 + 3;
      });
      y += 4;
    });
  } else {
    // Fallback synthetic body
    const bodyText = [
      `1. STATUTORY DECLARATION`,
      `The applicant institution, ${submission.institution.name} (FICTIONAL DEMO ENTITY), hereby declares`,
      `that the information submitted in this proforma is accurate and corresponds to institutional`,
      `records maintained in compliance with AICTE Approval Process Handbook 2024–2027.`,
      ``,
      `2. VERIFICATION STATUS`,
      `Record status is marked as "${doc.verificationStatus.toUpperCase()}". Reviewers should cross-reference`,
      `declared metrics against regional inspection records and state government notifications.`,
      ``,
      `3. DATA PROVENANCE NOTICE`,
      `All figures, names, dates, and identifiers in this sample document are entirely synthetic and`,
      `have been generated exclusively for the AICTE VerifyAI SIH prototype demonstration.`,
      `No real institutional data has been used.`,
    ];
    bodyText.forEach((line) => {
      y = checkPageBreak(pdf, y);
      if (line.match(/^\d\./)) {
        pdf.setFont('helvetica', 'bold');
        pdf.setFontSize(8);
        pdf.setTextColor(NAVY[0], NAVY[1], NAVY[2]);
      } else {
        pdf.setFont('helvetica', 'normal');
        pdf.setFontSize(8);
        pdf.setTextColor(SLATE[0], SLATE[1], SLATE[2]);
      }
      if (line === '') { y += 3; return; }
      const lines = pdf.splitTextToSize(line, pw - 27);
      pdf.text(lines, 15, y);
      y += lines.length * 4.5 + 1;
    });
  }

  // ── Closing watermark box ──────────────────────────────────────────────────
  y = checkPageBreak(pdf, y, 18);
  y += 6;
  pdf.setFillColor(254, 243, 199);
  pdf.roundedRect(12, y, pw - 24, 12, 2, 2, 'F');
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(7.5);
  pdf.setTextColor(AMBER[0], AMBER[1], AMBER[2]);
  pdf.text(
    '[ END OF SAMPLE DOCUMENT — SAMPLE / DEMO — NOT AN OFFICIAL DOCUMENT ]',
    pw / 2,
    y + 7.5,
    { align: 'center' },
  );

  return pdf;
}

/** Derive a clean, meaningful PDF filename from the EvidenceItem and Submission. */
export function pdfFilename(doc: EvidenceItem, submission: Submission): string {
  // Use whatever filename the doc already has, stripped of any non-pdf extension, or build one
  const base =
    doc.filename
      ? doc.filename.replace(/\.[^.]+$/, '')
      : `${safeStem(submission.institution.name)}_${doc.type}_${safeStem(doc.name, 30)}`;
  return `${base}_SAMPLE.pdf`;
}

// ─── Public API ───────────────────────────────────────────────────────────────

/** Download a single evidence document as a PDF. */
export function downloadSampleDocument(doc: EvidenceItem, submission: Submission): DownloadResult {
  try {
    const pdf = buildDocumentPdf(doc, submission);
    const filename = pdfFilename(doc, submission);
    const blob = pdf.output('blob');
    triggerBrowserDownload(filename, blob);
    return {
      success: true,
      filename,
      fileSizeBytes: blob.size,
      message: `Downloaded "${filename}" (${Math.round(blob.size / 1024)} KB PDF)`,
    };
  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : 'Unknown download error';
    return {
      success: false,
      filename: doc.name,
      fileSizeBytes: 0,
      message: `Download failed: ${errorMsg}`,
    };
  }
}

/**
 * Download all dossier documents as individual PDFs bundled in a ZIP file.
 * Each PDF inside the ZIP is a valid PDF with the watermark.
 */
export async function downloadAllDossierDocuments(submission: Submission): Promise<DownloadResult> {
  try {
    const zip = new JSZip();
    const cleanInst = safeStem(submission.institution.name);
    const cleanApp = submission.applicationId.replace(/[^a-zA-Z0-9]/g, '_');
    const zipFilename = `${cleanInst}_${cleanApp}_Evidence_Dossier_SAMPLE.zip`;

    // Add a README in the ZIP
    zip.file(
      'README.txt',
      [
        '================================================================================',
        'AICTE VerifyAI — Sample Evidence Dossier',
        '================================================================================',
        '',
        'IMPORTANT: SAMPLE / DEMO — NOT AN OFFICIAL DOCUMENT',
        '',
        `Institution : ${submission.institution.name} (FICTIONAL DEMO ENTITY)`,
        `Application : ${submission.applicationId}`,
        `Generated   : ${new Date().toISOString()}`,
        '',
        'This ZIP was generated by AICTE VerifyAI, a Smart India Hackathon prototype.',
        'All documents inside are synthetic demo PDFs for evaluation purposes only.',
        '',
        'Documents in this dossier:',
        ...submission.evidence.map(
          (ev, i) => `  ${i + 1}. ${pdfFilename(ev, submission)}  [${ev.type}]`,
        ),
        '',
        '================================================================================',
        '[END OF README]',
        '================================================================================',
      ].join('\n'),
    );

    // Add each evidence item as a PDF
    for (const ev of submission.evidence) {
      const pdf = buildDocumentPdf(ev, submission);
      const pdfBytes = pdf.output('arraybuffer');
      zip.file(pdfFilename(ev, submission), pdfBytes);
    }

    const zipBlob = await zip.generateAsync({ type: 'blob', compression: 'DEFLATE' });
    triggerBrowserDownload(zipFilename, zipBlob);

    return {
      success: true,
      filename: zipFilename,
      fileSizeBytes: zipBlob.size,
      message: `Downloaded dossier ZIP "${zipFilename}" — ${submission.evidence.length} PDF(s) inside`,
    };
  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : 'Unknown dossier export error';
    return {
      success: false,
      filename: 'Evidence_Dossier.zip',
      fileSizeBytes: 0,
      message: `Dossier download failed: ${errorMsg}`,
    };
  }
}

// ─── Compliance Scrutiny Review Report Generator ──────────────────────────────

/**
 * Builds an official-style, multi-page AICTE Compliance Review Report PDF
 * containing application summary, statutory findings, cross-document reconciliation,
 * reviewer remarks, and audit trail history.
 */
export function buildComplianceReviewReportPdf(
  submission: Submission,
  auditEvents: AuditEvent[] = [],
): jsPDF {
  const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const pw = pdf.internal.pageSize.getWidth();

  drawWatermark(pdf);
  drawFooter(pdf);

  // ── Header Band ────────────────────────────────────────────────────────────
  pdf.setFillColor(26, 13, 24); // #1A0D18
  pdf.rect(0, 0, pw, 38, 'F');

  // Cherry rose accent line
  pdf.setFillColor(193, 78, 131); // #C14E83
  pdf.rect(0, 38, pw, 2.5, 'F');

  // VerifyAI brand title
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(15);
  pdf.setTextColor(255, 255, 255);
  pdf.text('AICTE VerifyAI', 14, 15);

  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(8);
  pdf.setTextColor(248, 229, 237); // #F8E5ED
  pdf.text('Institutional Compliance Scrutiny & Regulatory Verification Report', 14, 22);
  pdf.text('Statutory Framework: AICTE Approval Process Handbook (APH) 2024–2027', 14, 28);

  // Right metadata block
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(8);
  pdf.setTextColor(255, 255, 255);
  pdf.text(`Application ID: ${submission.applicationId}`, pw - 14, 14, { align: 'right' });
  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(7.5);
  pdf.setTextColor(236, 217, 226);
  pdf.text(`AICTE ID: ${submission.institution.aicteId}`, pw - 14, 20, { align: 'right' });
  pdf.text(`Generated: ${new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}`, pw - 14, 26, { align: 'right' });
  pdf.text(`Status: ${submission.status.toUpperCase().replace(/_/g, ' ')}`, pw - 14, 32, { align: 'right' });

  let y = 47;

  // ── Advisory / Ethics Notice Bar ───────────────────────────────────────────
  pdf.setFillColor(253, 242, 246); // #FDF2F6
  pdf.setDrawColor(236, 217, 226); // #ECD9E2
  pdf.roundedRect(12, y, pw - 24, 10, 2, 2, 'FD');
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(7.5);
  pdf.setTextColor(170, 71, 119); // #AA4777
  pdf.text(
    'REGULATORY SCRUTINY REPORT · AICTE Technical Education Compliance Verification Cell',
    pw / 2,
    y + 6.5,
    { align: 'center' },
  );
  y += 16;

  // ── Section 1: Institution & Case Metadata ─────────────────────────────────
  y = drawSection(pdf, '1. Institution & Application Summary', y);

  const metaRows: [string, string][] = [
    ['Applicant Institution', submission.institution.name],
    ['AICTE Permanent ID', submission.institution.aicteId],
    ['Location & State', `${submission.institution.city}, ${submission.institution.state}`],
    ['Program / Category', submission.category],
    ['Application ID', submission.applicationId],
    ['Date of Submission', new Date(submission.submittedAt).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })],
    ['Current Review Status', submission.status.toUpperCase().replace(/_/g, ' ')],
    ['Priority Scrutiny Score', `${submission.priorityScore} / 100 (Automated Risk Ranking)`],
    ['Assigned Review Officer', submission.assignedTo ?? 'Priya Venkataraman (Senior Compliance Reviewer)'],
  ];

  metaRows.forEach(([k, v], i) => {
    y = checkPageBreak(pdf, y, 10);
    y = drawKVRow(pdf, k, v, y, i % 2 === 0);
  });
  y += 4;

  // ── Section 2: Compliance Executive Assessment ─────────────────────────────
  y = checkPageBreak(pdf, y, 35);
  y = drawSection(pdf, '2. Compliance Executive Assessment', y);

  const criticalFindings = submission.findings.filter((f) => f.severity === 'critical');
  const majorFindings = submission.findings.filter((f) => f.severity === 'major');
  const minorFindings = submission.findings.filter((f) => f.severity === 'minor');

  // Summary Metrics Box
  pdf.setFillColor(245, 247, 250);
  pdf.roundedRect(12, y, pw - 24, 16, 2, 2, 'F');
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(8.5);
  pdf.setTextColor(NAVY[0], NAVY[1], NAVY[2]);
  pdf.text('Dossier Findings Summary:', 16, y + 6);

  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(8);
  pdf.setTextColor(185, 28, 28);
  pdf.text(`Critical: ${criticalFindings.length}`, 16, y + 12);
  pdf.setTextColor(217, 119, 6);
  pdf.text(`Major: ${majorFindings.length}`, 50, y + 12);
  pdf.setTextColor(131, 24, 67);
  pdf.text(`Minor: ${minorFindings.length}`, 84, y + 12);
  pdf.setTextColor(SLATE[0], SLATE[1], SLATE[2]);
  pdf.text(`Cross-Doc Checks: ${submission.crossDocComparisons?.length ?? 0}`, 118, y + 12);
  pdf.text(`Evidence Files: ${submission.evidence.length}`, 162, y + 12);
  y += 22;

  // Statutory Advisory Note
  y = checkPageBreak(pdf, y, 22);
  pdf.setFillColor(254, 252, 232);
  pdf.roundedRect(12, y, pw - 24, 13, 2, 2, 'F');
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(7.5);
  pdf.setTextColor(180, 83, 9);
  pdf.text('REVIEWER ADVISORY ON EVIDENCE & FINDINGS', 16, y + 5);
  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(7);
  pdf.setTextColor(55, 65, 81);
  const advisoryText =
    'Automated findings indicate discrepancies or risk indicators for human scrutiny. They do not constitute conclusive proof of fraud or forgery. Review officers must inspect cited documents and apply statutory hearing procedures.';
  const advLines = pdf.splitTextToSize(advisoryText, pw - 32);
  pdf.text(advLines, 16, y + 9);
  y += 18;

  // ── Section 3: Itemized Regulatory Findings & Evidence ─────────────────────
  y = checkPageBreak(pdf, y, 35);
  y = drawSection(pdf, `3. Itemized Regulatory Findings (${submission.findings.length})`, y);

  if (submission.findings.length === 0) {
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(8);
    pdf.setTextColor(16, 185, 129);
    pdf.text('No regulatory non-compliance findings flagged for this application.', 16, y + 4);
    y += 10;
  } else {
    submission.findings.forEach((f, idx) => {
      y = checkPageBreak(pdf, y, 38);

      // Finding Header banner
      const isCrit = f.severity === 'critical';
      const isMaj = f.severity === 'major';
      pdf.setFillColor(isCrit ? 254 : isMaj ? 254 : 253, isCrit ? 242 : isMaj ? 243 : 242, isCrit ? 242 : isMaj ? 199 : 246);
      pdf.roundedRect(12, y, pw - 24, 7, 1.5, 1.5, 'F');

      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(8);
      pdf.setTextColor(isCrit ? 185 : isMaj ? 180 : 131, isCrit ? 28 : isMaj ? 83 : 24, isCrit ? 28 : isMaj ? 9 : 67);
      pdf.text(
        `Finding ${idx + 1} [${f.severity.toUpperCase()}] · ${f.category}`,
        16,
        y + 5,
      );
      y += 10;

      // Description
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(8);
      pdf.setTextColor(30, 30, 30);
      const descLines = pdf.splitTextToSize(`Issue: ${f.description}`, pw - 30);
      pdf.text(descLines, 16, y);
      y += descLines.length * 4.2 + 2;

      // Regulatory Rule
      if (f.ruleOrCheck) {
        y = checkPageBreak(pdf, y, 14);
        pdf.setFont('helvetica', 'bold');
        pdf.setFontSize(7.5);
        pdf.setTextColor(53, 29, 49); // #351D31
        pdf.text('Regulatory Standard / Rule:', 16, y);
        pdf.setFont('helvetica', 'normal');
        pdf.setFontSize(7.5);
        pdf.setTextColor(71, 85, 105);
        const ruleLines = pdf.splitTextToSize(f.ruleOrCheck, pw - 60);
        pdf.text(ruleLines, 60, y);
        y += ruleLines.length * 4.2 + 2;
      }

      // Analysis Rationale & Why it matters
      if (f.reason) {
        y = checkPageBreak(pdf, y, 16);
        pdf.setFont('helvetica', 'bold');
        pdf.setFontSize(7.5);
        pdf.setTextColor(53, 29, 49);
        pdf.text('Analysis Rationale:', 16, y);
        pdf.setFont('helvetica', 'normal');
        pdf.setFontSize(7.5);
        pdf.setTextColor(55, 65, 81);
        const reasonLines = pdf.splitTextToSize(f.reason, pw - 60);
        pdf.text(reasonLines, 60, y);
        y += reasonLines.length * 4.2 + 2;
      }

      // Evidentiary Source
      y = checkPageBreak(pdf, y, 10);
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(7.5);
      pdf.setTextColor(71, 85, 105);
      pdf.text(
        `Evidence Source: ${f.documentName ?? 'Submitted Dossier'}${f.pageNumber ? ` (Page ${f.pageNumber})` : ''}`,
        16,
        y,
      );
      y += 5;

      // Recommended Next Step
      if (f.reviewerNextStep) {
        y = checkPageBreak(pdf, y, 14);
        pdf.setFillColor(240, 253, 244);
        pdf.roundedRect(16, y, pw - 32, 8, 1, 1, 'F');
        pdf.setFont('helvetica', 'bold');
        pdf.setFontSize(7);
        pdf.setTextColor(21, 128, 61);
        pdf.text('Recommended Action:', 19, y + 5);
        pdf.setFont('helvetica', 'normal');
        const actLines = pdf.splitTextToSize(f.reviewerNextStep, pw - 75);
        pdf.text(actLines, 54, y + 5);
        y += Math.max(9, actLines.length * 4 + 4);
      }

      y += 4;
    });
  }

  // ── Section 4: Cross-Document Parameter Reconciliation ─────────────────────
  if (submission.crossDocComparisons && submission.crossDocComparisons.length > 0) {
    y = checkPageBreak(pdf, y, 35);
    y = drawSection(pdf, `4. Cross-Document Reconciliation (${submission.crossDocComparisons.length} Parameters Checked)`, y);

    submission.crossDocComparisons.forEach((comp) => {
      y = checkPageBreak(pdf, y, 30);

      // Parameter Box Header
      pdf.setFillColor(comp.hasDiscrepancy ? 254 : 240, comp.hasDiscrepancy ? 243 : 253, comp.hasDiscrepancy ? 199 : 244);
      pdf.roundedRect(12, y, pw - 24, 7, 1.5, 1.5, 'F');
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(8);
      pdf.setTextColor(comp.hasDiscrepancy ? 180 : 21, comp.hasDiscrepancy ? 83 : 128, comp.hasDiscrepancy ? 9 : 61);
      pdf.text(
        `${comp.fieldName} · ${comp.statusText}`,
        16,
        y + 5,
      );
      y += 10;

      // Table of extracted values from compared documents
      comp.entries.forEach((entry, eIdx) => {
        y = checkPageBreak(pdf, y, 8);
        pdf.setFont('helvetica', 'bold');
        pdf.setFontSize(7.5);
        pdf.setTextColor(SLATE[0], SLATE[1], SLATE[2]);
        pdf.text(`[Doc ${eIdx + 1}] ${entry.documentName} (p.${entry.sourcePage}):`, 16, y);

        pdf.setFont('helvetica', entry.isMismatched ? 'bold' : 'normal');
        pdf.setFontSize(7.5);
        pdf.setTextColor(entry.isMismatched ? 185 : 30, entry.isMismatched ? 28 : 30, entry.isMismatched ? 28 : 30);
        const valLines = pdf.splitTextToSize(entry.extractedValue, pw - 90);
        pdf.text(valLines, 85, y);
        y += Math.max(6, valLines.length * 4 + 1);
      });

      // Guidance
      if (comp.humanReviewRecommendation) {
        y = checkPageBreak(pdf, y, 10);
        pdf.setFont('helvetica', 'italic');
        pdf.setFontSize(7);
        pdf.setTextColor(71, 85, 105);
        const recLines = pdf.splitTextToSize(`Recommendation: ${comp.humanReviewRecommendation}`, pw - 32);
        pdf.text(recLines, 16, y);
        y += recLines.length * 4 + 3;
      }
      y += 3;
    });
  }

  // ── Section 5: Reviewer Remarks & Timeline ─────────────────────────────────
  const notesList = submission.reviewerNotesList ?? [];
  if (notesList.length > 0 || submission.reviewNotes) {
    y = checkPageBreak(pdf, y, 30);
    y = drawSection(pdf, '5. Reviewer Remarks & Official Directives', y);

    if (submission.reviewNotes) {
      y = checkPageBreak(pdf, y, 14);
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(8);
      pdf.setTextColor(53, 29, 49);
      pdf.text('Current Review Directive / Finding Note:', 16, y);
      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(7.5);
      pdf.setTextColor(30, 30, 30);
      const noteLines = pdf.splitTextToSize(submission.reviewNotes, pw - 30);
      pdf.text(noteLines, 16, y + 5);
      y += noteLines.length * 4.2 + 8;
    }

    notesList.forEach((n) => {
      y = checkPageBreak(pdf, y, 16);
      pdf.setFillColor(248, 249, 250);
      pdf.roundedRect(14, y, pw - 28, 6, 1, 1, 'F');
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(7.5);
      pdf.setTextColor(37, 99, 235);
      pdf.text(`${n.author} (${n.role}) · [${n.category.toUpperCase()}]`, 17, y + 4.5);
      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(7);
      pdf.setTextColor(100, 116, 139);
      pdf.text(new Date(n.timestamp).toLocaleString('en-IN'), pw - 18, y + 4.5, { align: 'right' });
      y += 8;

      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(7.5);
      pdf.setTextColor(30, 30, 30);
      const textLines = pdf.splitTextToSize(n.text, pw - 34);
      pdf.text(textLines, 17, y);
      y += textLines.length * 4 + 4;
    });
  }

  // ── Section 6: Audit History Trail ─────────────────────────────────────────
  const relevantEvents = auditEvents.filter(
    (e) => e.submissionId === submission.id || e.applicationId === submission.applicationId,
  );
  if (relevantEvents.length > 0) {
    y = checkPageBreak(pdf, y, 30);
    y = drawSection(pdf, `6. Chronological Audit Trail (${relevantEvents.length} Events)`, y);

    relevantEvents.slice(0, 10).forEach((ev) => {
      y = checkPageBreak(pdf, y, 10);
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(7);
      pdf.setTextColor(53, 29, 49);
      pdf.text(ev.action.toUpperCase().replace(/_/g, ' '), 16, y);

      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(7);
      pdf.setTextColor(71, 85, 105);
      pdf.text(`By: ${ev.performedBy}`, 65, y);
      pdf.text(new Date(ev.timestamp).toLocaleString('en-IN'), pw - 16, y, { align: 'right' });

      if (ev.details) {
        y += 4;
        const detLines = pdf.splitTextToSize(ev.details, pw - 36);
        pdf.text(detLines, 16, y);
        y += detLines.length * 3.5;
      }
      y += 3;
    });
  }

  // ── Official Sign-off & Closing Block ──────────────────────────────────────
  y = checkPageBreak(pdf, y, 32);
  y += 4;
  pdf.setDrawColor(200, 210, 225);
  pdf.setLineWidth(0.4);
  pdf.line(14, y, pw - 14, y);
  y += 8;

  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(7.5);
  pdf.setTextColor(53, 29, 49);
  pdf.text('Scrutiny Officer Sign-off:', 16, y);
  pdf.text('Regional Directorate Verification Cell:', pw - 80, y);

  y += 12;
  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(7);
  pdf.setTextColor(71, 85, 105);
  pdf.text('Priya Venkataraman, Senior Compliance Reviewer', 16, y);
  pdf.text('AICTE Regional Directorate · Technical Education', pw - 80, y);

  y += 4;
  pdf.text(`Recorded Date: ${new Date().toISOString().slice(0, 10)}`, 16, y);
  pdf.text('Digital Stamp: VERIFIED — AY 2026–2027 CYCLE', pw - 80, y);

  return pdf;
}

/**
 * Downloads the complete, professional AICTE Compliance Scrutiny Report as a PDF.
 */
export function downloadReviewSummaryReport(
  submission: Submission,
  auditEvents: AuditEvent[] = [],
): DownloadResult {
  try {
    const pdf = buildComplianceReviewReportPdf(submission, auditEvents);
    const cleanInst = safeStem(submission.institution.name);
    const cleanApp = submission.applicationId.replace(/[^a-zA-Z0-9]/g, '_');
    const filename = `${cleanInst}_${cleanApp}_Compliance_Review_Report.pdf`;
    const blob = pdf.output('blob');
    triggerBrowserDownload(filename, blob);

    return {
      success: true,
      filename,
      fileSizeBytes: blob.size,
      message: `Downloaded official Compliance Review Report "${filename}" (${Math.round(blob.size / 1024)} KB PDF)`,
    };
  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : 'Unknown report generation error';
    return {
      success: false,
      filename: 'Compliance_Review_Report.pdf',
      fileSizeBytes: 0,
      message: `Report generation failed: ${errorMsg}`,
    };
  }
}
